const ENGLISH_MONTHS: Record<string, string> = {
  Januari: "January", Februari: "February", Maret: "March", April: "April",
  Mei: "May", Juni: "June", Juli: "July", Agustus: "August", September: "September",
  Oktober: "October", November: "November", Desember: "December",
  Jan: "Jan", Feb: "Feb", Mar: "Mar", Apr: "Apr", Jun: "Jun", Jul: "Jul", Agu: "Aug", Sep: "Sep", Okt: "Oct", Nov: "Nov", Des: "Dec",
};
const DATE_ONLY = new RegExp(`^(?:\\d{1,2}(?:\\s*[–-]\\s*\\d{1,2})?\\s+)?(${Object.keys(ENGLISH_MONTHS).join("|")})\\s+\\d{4}$`);

export function reviewedEnglishFor(source: string): string | undefined {
  const reviewed = REVIEWED_ENGLISH_COPY[source];
  if (reviewed !== undefined) return reviewed;

  // These values carry no untranslated prose. Preserve the actual amount,
  // contact, and legal registration instead of sending them to a translator.
  if (/^(?:Rp|IDR|USD|EUR|GBP|\$)\s*[\d.,]+$/.test(source)
    || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(source)
    || /^(?:WhatsApp\s+\+?[\d ()-]+|Instagram\s+@[\w.]+)$/.test(source)
    || /^[·•]?\s*NIB\s+[\d .-]+$/.test(source)) return source;

  const startingPrice = /^Mulai ((?:Rp|IDR|USD|EUR|GBP|\$)\s*[\d.,]+)$/.exec(source);
  if (startingPrice) return `From ${startingPrice[1]}`;
  const verification = /^Terakhir diverifikasi (.+)$/.exec(source);
  if (verification && DATE_ONLY.test(verification[1])) return `Last verified ${reviewedEnglishFor(verification[1])}`;
  const countryLabel = /^(Bendera|Lihat informasi visa) (.+)$/.exec(source);
  if (countryLabel && REVIEWED_ENGLISH_COPY[countryLabel[2]]) {
    return `${countryLabel[1] === "Bendera" ? "Flag of" : "View visa information for"} ${REVIEWED_ENGLISH_COPY[countryLabel[2]]}`;
  }
  const date = DATE_ONLY.exec(source);
  if (date) return source.replace(date[1], ENGLISH_MONTHS[date[1]]);
  return undefined;
}

export function normalizeEnglishTranslation(value: string): string {
  return value
    .replace(/(\d)\s*[—–]\s*(\d)/gu, "$1 to $2")
    .replace(/\s*[—–]\s*/gu, ", ");
}
